    <script>
        function changeText(event, category) {
            document.getElementById('descuentos').className = 'd-none';
            document.getElementById('proyectos').className = 'd-none';
            document.getElementById('consultoria').className = 'd-none';
            document.getElementById('soporte').className = 'd-none';
            document.getElementById('capacitaciones').className = 'd-none';
            document.getElementById('noticias').className = 'd-none';
            const pathsDescuentos = document.querySelectorAll('#descuentos-svg path');
            const pathsProyectos = document.querySelectorAll('#proyectos-svg path');
            const pathsConsultoria = document.querySelectorAll('#consultoria-svg path');
            const pathsSoporte = document.querySelectorAll('#soporte-svg path');
            const pathsCapacitaciones = document.querySelectorAll('#capacitaciones-svg path');
            const pathsNoticias = document.querySelectorAll('#noticias-svg path');
            pathsDescuentos.forEach(path => {
                path.setAttribute('fill', '#FF5100');
            });
            pathsProyectos.forEach(path => {
                path.setAttribute('fill', '#FF5100');
            });
            pathsConsultoria.forEach(path => {
                path.setAttribute('fill', '#FF5100');
            });
            pathsSoporte.forEach(path => {
                path.setAttribute('fill', '#FF5100');
            });
            pathsCapacitaciones.forEach(path => {
                path.setAttribute('fill', '#FF5100');
            });
            pathsNoticias.forEach(path => {
                path.setAttribute('fill', '#FF5100');
            });

            switch (category) {
                case 'descuentos':
                    document.getElementById('descuentos').className = 'd-block';
                    pathsDescuentos.forEach(path => {
                        path.setAttribute('fill', '#24537B');
                    });
                    break;
                case 'proyectos':
                    document.getElementById('proyectos').className = 'd-block';
                    pathsProyectos.forEach(path => {
                        path.setAttribute('fill', '#24537B');
                    });
                    break;
                case 'consultoria':
                    document.getElementById('consultoria').className = 'd-block';
                    pathsConsultoria.forEach(path => {
                        path.setAttribute('fill', '#24537B');
                    });
                    break;
                case 'soporte':
                    document.getElementById('soporte').className = 'd-block';
                    pathsSoporte.forEach(path => {
                        path.setAttribute('fill', '#24537B');
                    });
                    break;
                case 'capacitaciones':
                    document.getElementById('capacitaciones').className = 'd-block';
                    pathsCapacitaciones.forEach(path => {
                        path.setAttribute('fill', '#24537B');
                    });
                    break;
                case 'noticias':
                    document.getElementById('noticias').className = 'd-block m-0 p-0';
                    pathsNoticias.forEach(path => {
                        path.setAttribute('fill', '#24537B');
                    });
                    break;
                default:
                    break;
            }
        }



        function activarColor(event, path) {
            document.getElementById('coahuilaSvg').setAttribute('fill', '#24537B');
            document.getElementById('nuevoleonSvg').setAttribute('fill', '#24537B');
            switch (path) {
                case 'coahuilaSvg':
                    document.getElementById('coahuilaSvg').setAttribute('fill', '#FF5100');
                    document.getElementById('card-coahuila').className = 'd-block';
                    document.getElementById('card-nuevoleon').className = 'd-none';
                    break;
                case 'nuevoleonSvg':
                    document.getElementById('nuevoleonSvg').setAttribute('fill', '#FF5100');
                    document.getElementById('card-nuevoleon').className = 'd-block';
                    document.getElementById('card-coahuila').className = 'd-none';
                    break;
            }

        }
    </script>
